package com.hmdp.ai.application.dto.mcp;import com.hmdp.ai.domain.mcp.McpServer;import java.time.Instant;public final class McpServerResponse {private final String id,code,name,namespace,transport,endpoint,healthStatus,status;private final int timeoutMs;private final boolean secretConfigured,allowPrivateNetwork,enabled;private final Instant lastSyncAt;public McpServerResponse(McpServer s){id=s.getId();code=s.getCode();name=s.getName();namespace=s.getNamespace();transport=s.getTransport().name();endpoint=s.getEndpoint();healthStatus=s.getHealthStatus();status=s.getStatus();timeoutMs=s.getTimeoutMs();secretConfigured=s.getSecretRef()!=null&&!s.getSecretRef().isEmpty();allowPrivateNetwork=s.isAllowPrivateNetwork();enabled=s.isEnabled();lastSyncAt=s.getLastSyncAt();}public String getId(){return id;}public String getCode(){return code;}public String getName(){return name;}public String getNamespace(){return namespace;}public String getTransport(){return transport;}public String getEndpoint(){return endpoint;}public String getHealthStatus(){return healthStatus;}public String getStatus(){return status;}public int getTimeoutMs(){return timeoutMs;}public boolean isSecretConfigured(){return secretConfigured;}public boolean isAllowPrivateNetwork(){return allowPrivateNetwork;}public boolean isEnabled(){return enabled;}public Instant getLastSyncAt(){return lastSyncAt;}}
